core_reasoning_1:
\section*{Claim}
Let the Landau-gauge scalar gluon propagator be written as \(G_A(p;\mu)=1/(Z_A(p;\mu)p^2)\). If \(Z_A(p;\mu)\) obeys the multiplicative renormalisation-group equation used in the paper, then the non-zero complex zero set of \(Z_A(-\omega^2;\mu)\) is independent of \(\mu\). Hence the screening definition \(\omega_{\rm gap}=(1+i\gamma_{\rm gap})m_{\rm gap}\) gives a renormalisation-group invariant \(m_{\rm gap}\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &G_A(p;\mu)=\frac{1}{Z_A(p;\mu)p^2}.\\
\text{(P2)}\quad &\left(\mu\frac{d}{d\mu}-2\gamma_A(\mu)\right)Z_A(p;\mu)=0\quad\text{at fixed }p.\\
\text{(P3)}\quad &\omega_{\rm gap}:=\min_{\omega_s\ne0}\{\operatorname{Re}\omega_s\mid Z_A(-\omega_s^2;\mu)=0\}.\\
\text{(P4)}\quad &\omega_{\rm gap}=(1+i\gamma_{\rm gap})m_{\rm gap},\qquad m_{\rm gap}:=\operatorname{Re}\omega_{\rm gap}.\\
\text{(P5)}\quad &R(\mu,\mu_0):=\exp\left(2\int_{\mu_0}^{\mu}\gamma_A(\mu')\frac{d\mu'}{\mu'}\right),\qquad R(\mu,\mu_0)\ne0.\\
\text{(P6)}\quad &\text{The ordering by }\operatorname{Re}\omega_s\text{ is unchanged if the zero set is unchanged.}
\end{aligned}
\]

\section*{Derivation}
For fixed momentum argument \(p\), rewrite (P2) as an ordinary differential equation in \(\mu\):
\begin{align}
\mu\frac{d}{d\mu}Z_A(p;\mu)&=2\gamma_A(\mu)Z_A(p;\mu) &&\text{by (P2)},\\
\frac{d}{d\mu}\left[R(\mu,\mu_0)^{-1}Z_A(p;\mu)\right]
&=R^{-1}\frac{dZ_A}{d\mu}+Z_A\frac{dR^{-1}}{d\mu} &&\text{product rule},\\
&=R^{-1}\frac{2\gamma_A}{\mu}Z_A-Z_A R^{-1}\frac{2\gamma_A}{\mu} &&\text{by (P2) and (P5)},\\
&=0.
\end{align}
Therefore
\begin{align}
R(\mu,\mu_0)^{-1}Z_A(p;\mu)&=Z_A(p;\mu_0),\\
Z_A(p;\mu)&=R(\mu,\mu_0)Z_A(p;\mu_0). \label{eq:rgzero}
\end{align}
Apply \eqref{eq:rgzero} at \(p=-\omega^2\):
\begin{align}
Z_A(-\omega^2;\mu)=0
&\Longleftrightarrow R(\mu,\mu_0)Z_A(-\omega^2;\mu_0)=0 &&\text{by \eqref{eq:rgzero}},\\
&\Longleftrightarrow Z_A(-\omega^2;\mu_0)=0 &&\text{because }R(\mu,\mu_0)\ne0\text{ by (P5)}.
\end{align}
Thus the non-zero zero set is independent of \(\mu\). By (P3) and (P6), the selected zero \(\omega_{\rm gap}\) is independent of \(\mu\). By (P4), its real part is also independent of \(\mu\):
\begin{align}
\mu\frac{d}{d\mu}m_{\rm gap}
&=\mu\frac{d}{d\mu}\operatorname{Re}\omega_{\rm gap} &&\text{by (P4)},\\
&=\operatorname{Re}\left(\mu\frac{d\omega_{\rm gap}}{d\mu}\right),\\
&=0.
\end{align}

\section*{Final Result}
\[
\boxed{\mu\frac{d}{d\mu}m_{\rm gap}=0}
\]
\hfill$\blacksquare$

core_reasoning_2:
\section*{Claim}
The dressing of a classical massive propagator, \(D_m(p):=p^2/(p^2+m^2)\), has no finite positive-momentum maximum. Therefore, the finite peak condition used in the paper for \(Z_A^{-1}(p)\) cannot be produced by the classical massive form alone.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &D_m(p):=\frac{p^2}{p^2+m^2}.\\
\text{(P2)}\quad &m>0,\\quad p\ge0.\\
\text{(P3)}\quad &\text{A finite interior maximum at }p_*>0\text{ requires }D_m'(p_*)=0\text{ and a sign change from }+\text{ to }-.\\
\text{(P4)}\quad &\frac{d}{dp}\left(\frac{u(p)}{v(p)}\right)=\frac{u'(p)v(p)-u(p)v'(p)}{v(p)^2}\quad\text{where }v(p)\ne0.
\end{aligned}
\]

\section*{Derivation}
Differentiate \(D_m\):
\begin{align}
\frac{dD_m}{dp}
&=\frac{(2p)(p^2+m^2)-p^2(2p)}{(p^2+m^2)^2} &&\text{by (P1) and (P4)},\\
&=\frac{2p^3+2pm^2-2p^3}{(p^2+m^2)^2} &&\text{expanding the numerator},\\
&=\frac{2pm^2}{(p^2+m^2)^2}. \label{eq:massive-derivative}
\end{align}
For \(p>0\), (P2) gives
\begin{align}
2pm^2&>0,\\
(p^2+m^2)^2&>0,\\
\frac{dD_m}{dp}&>0 &&\text{by \eqref{eq:massive-derivative}}.
\end{align}
Thus \(D_m\) is strictly increasing for every \(p>0\). Hence there is no \(p_*>0\) at which the derivative changes from positive to negative, and (P3) excludes a finite interior maximum.

\section*{Final Result}
\[
\boxed{\forall p>0:\ \frac{d}{dp}\left(\frac{p^2}{p^2+m^2}\right)>0,\quad\text{so }D_m\text{ has no finite positive-momentum peak}}
\]
\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
For the SU(2) one-loop Polyakov-loop potential displayed in the paper, \(V_{\rm pert}(\phi)\) is minimised at \(\widetilde\phi=0\), yielding \(L=1\). If the low-temperature gapped-gluon contribution is exponentially suppressed so that the remaining effective potential has the opposite sign, then the minimum moves to \(\widetilde\phi=1/2\), yielding \(L=0\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &V_{\rm pert}(\phi)=\frac{\pi^2}{48}T^4\left[4\left(\widetilde\phi-\frac12\right)^2-1\right]^2.\\
\text{(P2)}\quad &\widetilde\phi:=\phi\bmod 1,\qquad 0\le\widetilde\phi<1.\\
\text{(P3)}\quad &L(\phi)=\cos(\pi\phi)\quad\text{for SU(2)}.\\
\text{(P4)}\quad &T>0.\\
\text{(P5)}\quad &\operatorname*{arg\,min}_{x}[-F(x)]=\operatorname*{arg\,max}_{x}F(x).\\
\text{(P6)}\quad &\cos(0)=1,\qquad \cos(\pi/2)=0.
\end{aligned}
\]

\section*{Derivation}
Define
\begin{align}
y&:=\widetilde\phi-\frac12,\\
F(y)&:=\left(4y^2-1\right)^2.
\end{align}
By (P2), \(-1/2\le y<1/2\). Since \(\pi^2T^4/48>0\) by (P4), minimising \(V_{\rm pert}\) is equivalent to minimising \(F\). The stationary points satisfy
\begin{align}
\frac{dF}{dy}
&=2(4y^2-1)(8y) &&\text{chain rule},\\
&=16y(4y^2-1),\\
\frac{dF}{dy}=0
&\Longleftrightarrow y=0\text{ or }y=\pm\frac12. \label{eq:stationary}
\end{align}
Evaluate \(F\) at the allowed stationary and boundary points:
\begin{align}
F(0)&=(-1)^2=1,\\
F(-1/2)&=(1-1)^2=0,\\
\lim_{y\to(1/2)^-}F(y)&=0.
\end{align}
Thus on the fundamental interval \(0\le\widetilde\phi<1\), the perturbative minimum is attained at \(y=-1/2\), i.e. \(\widetilde\phi=0\), while the maximum is attained at \(y=0\), i.e. \(\widetilde\phi=1/2\):
\begin{align}
\operatorname*{arg\,min}_{0\le\widetilde\phi<1}V_{\rm pert}(\phi)&=\{0\},\\
\operatorname*{arg\,max}_{0\le\widetilde\phi<1}V_{\rm pert}(\phi)&=\{1/2\}.
\end{align}
For the sign-reversed low-temperature effective potential,
\begin{align}
\operatorname*{arg\,min}_{0\le\widetilde\phi<1}[-V_{\rm pert}(\phi)]
&=\operatorname*{arg\,max}_{0\le\widetilde\phi<1}V_{\rm pert}(\phi) &&\text{by (P5)},\\
&=\{1/2\}.
\end{align}
The corresponding Polyakov-loop values are
\begin{align}
L(0)&=\cos(0)=1 &&\text{by (P3) and (P6)},\\
L(1/2)&=\cos(\pi/2)=0 &&\text{by (P3) and (P6)}.
\end{align}

\section*{Final Result}
\[
\boxed{\operatorname*{arg\,min}V_{\rm pert}:\widetilde\phi=0,\ L=1;\qquad \operatorname*{arg\,min}(-V_{\rm pert}):\widetilde\phi=\frac12,\ L=0}
\]
\hfill$\blacksquare$

core_reasoning_4:
\section*{Claim}
In the Polyakov-loop mode-potential loop integral, the zero Matsubara-shift radial integrand is exactly the propagator dressing \(Z_i^{-1}(p)\). Hence a deformation of \(G_i\) that leaves \(Z_i^{-1}\) unchanged leaves that zero-shift loop contribution unchanged.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &G_i(p)=\frac{1}{Z_i(p)}\frac{1}{p^2},\qquad i\in\{A,c\}.\\
\text{(P2)}\quad &p_0:=2\pi T(n+\nu_j).\\
\text{(P3)}\quad &I_i(p_0):=\int\frac{d^3p}{(2\pi)^3}G_i\left(\sqrt{p_0^2+p^2}\right).\\
\text{(P4)}\quad &\int\frac{d^3p}{(2\pi)^3}h(p)=\int_0^\infty\frac{dp}{2\pi^2}p^2h(p)\quad\text{for radial }h.\\
\text{(P5)}\quad &\delta Z_i^{-1}(p):=p^2\delta G_i(p).\\
\text{(P6)}\quad &p_0=0\quad\text{for the zero-shift contribution}.
\end{aligned}
\]

\section*{Derivation}
Using the zero Matsubara shift,
\begin{align}
I_i(0)&=\int\frac{d^3p}{(2\pi)^3}G_i(p) &&\text{by (P3) and (P6)},\\
&=\int_0^\infty\frac{dp}{2\pi^2}p^2G_i(p) &&\text{by (P4)},\\
&=\int_0^\infty\frac{dp}{2\pi^2}p^2\left[\frac{1}{Z_i(p)}\frac{1}{p^2}\right] &&\text{by (P1)},\\
&=\int_0^\infty\frac{dp}{2\pi^2}Z_i^{-1}(p). \label{eq:zero-shift-dressing}
\end{align}
For a deformation of \(G_i\), the induced change is
\begin{align}
\delta I_i(0)&=\int_0^\infty\frac{dp}{2\pi^2}p^2\delta G_i(p) &&\text{varying the second line of \eqref{eq:zero-shift-dressing}},\\
&=\int_0^\infty\frac{dp}{2\pi^2}\delta Z_i^{-1}(p) &&\text{by (P5)}.
\end{align}
Therefore, if \(\delta Z_i^{-1}(p)=0\) for all \(p\) in the deformation support, every pointwise contribution to the last integral vanishes.

\section*{Final Result}
\[
\boxed{\delta Z_i^{-1}(p)=0\ \text{on the support of the deformation}\ \Longrightarrow\ \delta I_i(0)=0}
\]
\hfill$\blacksquare$

core_reasoning_5:
\section*{Claim}
For the scalar quark gap equation used in the paper, the gluon propagator enters the radial integral through the gluon dressing \(Z_A^{-1}(k)=k^2G_A(k)\). Consequently, an infrared deformation that is invisible in \(Z_A^{-1}\) produces no direct change in the scalar gap-equation integral.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &M_q(p)=\frac{2\alpha_s}{\pi^2}Z_q^{-1}(p)\int_0^\infty dk^2\,k^2G_A(k)f(p,k).\\
\text{(P2)}\quad &G_A(k)=\frac{1}{Z_A(k)}\frac{1}{k^2}.\\
\text{(P3)}\quad &\delta Z_A^{-1}(k):=k^2\delta G_A(k).\\
\text{(P4)}\quad &\alpha_s>0,\qquad Z_q(p)\ne0.\\
\text{(P5)}\quad &\text{The direct variation keeps }\alpha_s,\ Z_q(p),\text{ and }f(p,k)\text{ fixed.}
\end{aligned}
\]

\section*{Derivation}
First identify the dressing factor in the integrand:
\begin{align}
k^2G_A(k)
&=k^2\left[\frac{1}{Z_A(k)}\frac{1}{k^2}\right] &&\text{by (P2)},\\
&=Z_A^{-1}(k). \label{eq:gap-dressing}
\end{align}
Substitute \eqref{eq:gap-dressing} into the scalar gap equation:
\begin{align}
M_q(p)&=\frac{2\alpha_s}{\pi^2}Z_q^{-1}(p)\int_0^\infty dk^2\,Z_A^{-1}(k)f(p,k). \label{eq:gap-dressing-form}
\end{align}
Now vary the gluon input directly:
\begin{align}
\delta M_q(p)
&=\frac{2\alpha_s}{\pi^2}Z_q^{-1}(p)\int_0^\infty dk^2\,\delta\!\bigl(k^2G_A(k)\bigr)f(p,k) &&\text{by (P1) and (P5)},\\
&=\frac{2\alpha_s}{\pi^2}Z_q^{-1}(p)\int_0^\infty dk^2\,\delta Z_A^{-1}(k)f(p,k) &&\text{by (P3)}. \label{eq:delta-gap}
\end{align}
If \(\delta Z_A^{-1}(k)=0\) on the support of the deformation, the integrand in \eqref{eq:delta-gap} vanishes there; outside the support there is no deformation. Thus \(\delta M_q(p)=0\) for the direct scalar integral.

\section*{Final Result}
\[
\boxed{\delta Z_A^{-1}(k)=0\ \text{on the deformation support}\ \Longrightarrow\ \delta M_q(p)=0}
\]
\hfill$\blacksquare$

core_reasoning_6:
\section*{Claim}
The Pagels-Stokar expression used in the paper contains a four-dimensional radial measure factor \(q=p^2\). Therefore, if a deformation changes the scalar Pagels-Stokar integrand only for \(0\le q\le\nu^2\) and the induced scalar change is bounded there, then the resulting change in \(f_\pi^2\) is bounded by a term proportional to \(\nu^4\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &f_\pi^2=4N_c\int\frac{d^4p}{(2\pi)^4}\frac{\bar Z_2^2}{Z_q(p)}\frac{M_q(p)}{[p^2+M_q^2(p)]^2}\left[M_q(p)-\frac{p^2}{2}M_q'(p)\right].\\
\text{(P2)}\quad &q:=p^2,\qquad M_q'(p):=\partial_{p^2}M_q(p).\\
\text{(P3)}\quad &\int\frac{d^4p}{(2\pi)^4}H(p^2)=\frac{1}{16\pi^2}\int_0^\infty dq\,qH(q)\quad\text{for radial }H.\\
\text{(P4)}\quad &\delta H(q)=0\quad\text{for }q>\nu^2.\\
\text{(P5)}\quad &|\delta H(q)|\le C_\nu\quad\text{for }0\le q\le\nu^2,\quad C_\nu<\infty.\\
\text{(P6)}\quad &N_c>0,
\qquad \nu\ge0.
\end{aligned}
\]

\section*{Derivation}
Define the radial scalar integrand without the measure by
\begin{align}
H(q)&:=\frac{\bar Z_2^2}{Z_q(q)}\frac{M_q(q)}{[q+M_q^2(q)]^2}\left[M_q(q)-\frac{q}{2}\frac{dM_q}{dq}(q)\right].
\end{align}
Then (P1)--(P3) give
\begin{align}
f_\pi^2&=4N_c\frac{1}{16\pi^2}\int_0^\infty dq\,qH(q),\\
&=\frac{N_c}{4\pi^2}\int_0^\infty dq\,qH(q). \label{eq:ps-radial}
\end{align}
The deformation changes \eqref{eq:ps-radial} by
\begin{align}
\delta f_\pi^2
&=\frac{N_c}{4\pi^2}\int_0^\infty dq\,q\delta H(q),\\
&=\frac{N_c}{4\pi^2}\int_0^{\nu^2} dq\,q\delta H(q) &&\text{by (P4)}.
\end{align}
Taking absolute values,
\begin{align}
|\delta f_\pi^2|
&\le \frac{N_c}{4\pi^2}\int_0^{\nu^2} dq\,q|\delta H(q)| &&\text{triangle inequality},\\
&\le \frac{N_c}{4\pi^2}\int_0^{\nu^2} dq\,qC_\nu &&\text{by (P5)},\\
&=\frac{N_cC_\nu}{4\pi^2}\left[\frac{q^2}{2}\right]_{0}^{\nu^2},\\
&=\frac{N_cC_\nu}{8\pi^2}\nu^4.
\end{align}

\section*{Final Result}
\[
\boxed{|\delta f_\pi^2|\le\frac{N_cC_\nu}{8\pi^2}\nu^4}
\]
\hfill$\blacksquare$

core_reasoning_7:
\section*{Claim}
For the fitted decoupling-type gluon propagator in the paper, the deep-infrared limit is \(G_{A,{\rm fit}}(0)=1/(z_{\rm sat}m_{\rm gap}^2)\). Hence, if \(G_A(0)=1/m_{\rm sat}^2\), then \(m_{\rm sat}^2=z_{\rm sat}m_{\rm gap}^2\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &G_{A,{\rm fit}}(p)=\frac{1}{Z_{A,{\rm fit}}(p)p^2}.\\
\text{(P2)}\quad &Z_{A,{\rm fit}}(p)=Z_{A,{\rm ir}}(x)+Z_{A,{\rm uv}}(x),\qquad x:=\frac{p^2}{m_{\rm gap}^2}.\\
\text{(P3)}\quad &Z_{A,{\rm ir}}(x)=\frac{z_{\rm sat}/x-z_{\rm peak}-z_{\rm gh}\log(1+1/(c_-x))}{(1+c_+x)^2}.\\
\text{(P4)}\quad &Z_{A,{\rm uv}}(x)=z_{\rm uv}\left[1+c_{\rm uv}\log(1+c_+x)\right]^\gamma.\\
\text{(P5)}\quad &m_{\rm gap}>0,\quad z_{\rm sat}>0,\quad c_+>0,\quad c_->0.\\
\text{(P6)}\quad &\lim_{x\to0^+}x\log(1+1/(c_-x))=0,
\quad \lim_{x\to0^+}xZ_{A,{\rm uv}}(x)=0.\\
\text{(P7)}\quad &G_A(0):=\lim_{p\to0}G_A(p),\qquad G_A(0)=\frac{1}{m_{\rm sat}^2}.
\end{aligned}
\]

\section*{Derivation}
As \(p\to0\), \(x\to0^+\). Multiply the infrared fit by \(x\):
\begin{align}
xZ_{A,{\rm ir}}(x)
&=\frac{z_{\rm sat}-xz_{\rm peak}-xz_{\rm gh}\log(1+1/(c_-x))}{(1+c_+x)^2} &&\text{by (P3)},\\
\lim_{x\to0^+}xZ_{A,{\rm ir}}(x)
&=z_{\rm sat} &&\text{by (P5) and (P6)}.
\end{align}
The ultraviolet part contributes no term to \(xZ_{A,{\rm fit}}\) at \(x=0\):
\begin{align}
\lim_{x\to0^+}xZ_{A,{\rm fit}}(x)
&=\lim_{x\to0^+}xZ_{A,{\rm ir}}(x)+\lim_{x\to0^+}xZ_{A,{\rm uv}}(x) &&\text{by (P2)},\\
&=z_{\rm sat}+0 &&\text{by (P6)},\\
&=z_{\rm sat}. \label{eq:xz-limit}
\end{align}
Using \(p^2=m_{\rm gap}^2x\),
\begin{align}
G_{A,{\rm fit}}(0)
&=\lim_{p\to0}\frac{1}{Z_{A,{\rm fit}}(p)p^2} &&\text{by (P1)},\\
&=\lim_{x\to0^+}\frac{1}{Z_{A,{\rm fit}}(x)m_{\rm gap}^2x} &&\text{by (P2)},\\
&=\frac{1}{m_{\rm gap}^2\lim_{x\to0^+}xZ_{A,{\rm fit}}(x)},\\
&=\frac{1}{z_{\rm sat}m_{\rm gap}^2} &&\text{by \eqref{eq:xz-limit}}.
\end{align}
Combining this with \(G_A(0)=1/m_{\rm sat}^2\) in (P7),
\begin{align}
\frac{1}{m_{\rm sat}^2}&=\frac{1}{z_{\rm sat}m_{\rm gap}^2},\\
m_{\rm sat}^2&=z_{\rm sat}m_{\rm gap}^2.
\end{align}

\section*{Final Result}
\[
\boxed{G_{A,{\rm fit}}(0)=\frac{1}{z_{\rm sat}m_{\rm gap}^2},\qquad m_{\rm sat}^2=z_{\rm sat}m_{\rm gap}^2}
\]
\hfill$\blacksquare$

core_reasoning_8:
\section*{Claim}
For the fitted gluon dressing in the paper, the infrared part decouples in the ultraviolet, while the ultraviolet part carries the one-loop logarithmic scaling: as \(x\to\infty\), \(Z_{A,{\rm ir}}(x)\sim -z_{\rm peak}/(c_+^2x^2)\) and \(Z_{A,{\rm uv}}(x)\sim z_{\rm uv}c_{\rm uv}^{\gamma}(\log x)^\gamma\).

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &Z_{A,{\rm fit}}(p)=Z_{A,{\rm ir}}(x)+Z_{A,{\rm uv}}(x),\qquad x:=p^2/m_{\rm gap}^2.\\
\text{(P2)}\quad &Z_{A,{\rm ir}}(x)=\frac{z_{\rm sat}/x-z_{\rm peak}-z_{\rm gh}\log(1+1/(c_-x))}{(1+c_+x)^2}.\\
\text{(P3)}\quad &Z_{A,{\rm uv}}(x)=z_{\rm uv}\left[1+c_{\rm uv}\log(1+c_+x)\right]^\gamma.\\
\text{(P4)}\quad &c_+>0,
\quad c_->0,
\quad c_{\rm uv}>0,
\quad z_{\rm uv}>0,
\quad \gamma>0.\\
\text{(P5)}\quad &\log(1+u)=u+O(u^2)\quad\text{as }u\to0.\\
\text{(P6)}\quad &\log(1+c_+x)=\log x+\log c_++o(1)\quad\text{as }x\to\infty.
\end{aligned}
\]

\section*{Derivation}
For the infrared contribution, (P5) with \(u=1/(c_-x)\) gives
\begin{align}
\log\left(1+\frac{1}{c_-x}\right)&=\frac{1}{c_-x}+O(x^{-2}),\\
z_{\rm sat}/x-z_{\rm peak}-z_{\rm gh}\log\left(1+\frac{1}{c_-x}\right)
&=-z_{\rm peak}+\left(z_{\rm sat}-\frac{z_{\rm gh}}{c_-}\right)x^{-1}+O(x^{-2}). \label{eq:ir-num}
\end{align}
Also,
\begin{align}
(1+c_+x)^2&=c_+^2x^2\left(1+\frac{1}{c_+x}\right)^2,\\
\frac{1}{(1+c_+x)^2}&=\frac{1}{c_+^2x^2}\left(1+O(x^{-1})\right). \label{eq:ir-den}
\end{align}
Combining \eqref{eq:ir-num} and \eqref{eq:ir-den},
\begin{align}
Z_{A,{\rm ir}}(x)&=-\frac{z_{\rm peak}}{c_+^2x^2}+O(x^{-3}). \label{eq:ir-asymp}
\end{align}
For the ultraviolet part,
\begin{align}
1+c_{\rm uv}\log(1+c_+x)
&=1+c_{\rm uv}[\log x+\log c_++o(1)] &&\text{by (P6)},\\
&=c_{\rm uv}\log x\left[1+\frac{1+c_{\rm uv}\log c_++o(1)}{c_{\rm uv}\log x}\right],\\
\left[1+c_{\rm uv}\log(1+c_+x)\right]^\gamma
&=(c_{\rm uv}\log x)^\gamma[1+o(1)] &&\text{by (P4)}.
\end{align}
Substituting this in (P3),
\begin{align}
Z_{A,{\rm uv}}(x)&=z_{\rm uv}c_{\rm uv}^{\gamma}(\log x)^\gamma[1+o(1)]. \label{eq:uv-asymp}
\end{align}

\section*{Final Result}
\[
\boxed{Z_{A,{\rm ir}}(x)\sim -\frac{z_{\rm peak}}{c_+^2x^2},\qquad Z_{A,{\rm uv}}(x)\sim z_{\rm uv}c_{\rm uv}^{\gamma}(\log x)^\gamma\quad(x\to\infty)}
\]
\hfill$\blacksquare$

core_reasoning_9:
\section*{Claim}
The physical-unit rewriting of the fitted gluon dressing implies \(m_{\rm gap}[\mathrm{GeV}]=1/\sqrt{\eta}\), \(\bar c_\pm=\eta c_\pm\), and \(\bar z_{\rm sat}=z_{\rm sat}/\eta\), while \(z_{\rm peak}\), \(z_{\rm gh}\), \(z_{\rm uv}\), and \(c_{\rm uv}\) are invariant under this rewriting.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}\quad &x:=\frac{p^2}{m_{\rm gap}^2}.\\
\text{(P2)}\quad &\bar x:=p^2[\mathrm{GeV}^2].\\
\text{(P3)}\quad &x=\eta\bar x,
\qquad \eta:=\left(\frac{m_{\rm gap}^2}{1\,\mathrm{GeV}^2}\right)^{-1}.\\
\text{(P4)}\quad &Z_{A,{\rm ir}}(x)=\frac{z_{\rm sat}/x-z_{\rm peak}-z_{\rm gh}\log(1+1/(c_-x))}{(1+c_+x)^2}.\\
\text{(P5)}\quad &Z_{A,{\rm uv}}(x)=z_{\rm uv}\left[1+c_{\rm uv}\log(1+c_+x)\right]^\gamma.\\
\text{(P6)}\quad &m_{\rm gap}>0,
\qquad \eta>0.
\end{aligned}
\]

\section*{Derivation}
From (P3),
\begin{align}
\eta&=\left(\frac{m_{\rm gap}[\mathrm{GeV}]^2}{1}\right)^{-1},\\
\eta&=\frac{1}{m_{\rm gap}[\mathrm{GeV}]^2},\\
m_{\rm gap}[\mathrm{GeV}]&=\frac{1}{\sqrt{\eta}} &&\text{by (P6)}. \label{eq:mgap-eta}
\end{align}
Now substitute \(x=\eta\bar x\) into the infrared fit:
\begin{align}
Z_{A,{\rm ir}}(\eta\bar x)
&=\frac{z_{\rm sat}/(\eta\bar x)-z_{\rm peak}-z_{\rm gh}\log(1+1/(c_-\eta\bar x))}{(1+c_+\eta\bar x)^2} &&\text{by (P3) and (P4)},\\
&=\frac{(z_{\rm sat}/\eta)/\bar x-z_{\rm peak}-z_{\rm gh}\log(1+1/[(\eta c_-)\bar x])}{(1+(\eta c_+)\bar x)^2}. \label{eq:ir-rescaled}
\end{align}
Equation \eqref{eq:ir-rescaled} has the same form as (P4) in the variable \(\bar x\) if
\begin{align}
\bar z_{\rm sat}&:=\frac{z_{\rm sat}}{\eta},\\
\bar c_-&:=\eta c_-,\\
\bar c_+&:=\eta c_+,\\
\bar z_{\rm peak}&:=z_{\rm peak},\\
\bar z_{\rm gh}&:=z_{\rm gh}.
\end{align}
Likewise, for the ultraviolet term,
\begin{align}
Z_{A,{\rm uv}}(\eta\bar x)
&=z_{\rm uv}\left[1+c_{\rm uv}\log(1+c_+\eta\bar x)\right]^\gamma &&\text{by (P3) and (P5)},\\
&=z_{\rm uv}\left[1+c_{\rm uv}\log(1+\bar c_+\bar x)\right]^\gamma.
\end{align}
Thus \(z_{\rm uv}\) and \(c_{\rm uv}\) are unchanged by the rewriting.

\section*{Final Result}
\[
\boxed{m_{\rm gap}[\mathrm{GeV}]=\frac{1}{\sqrt{\eta}},\qquad \bar c_\pm=\eta c_\pm,\qquad \bar z_{\rm sat}=\frac{z_{\rm sat}}{\eta},\qquad \bar z_i=z_i\ (i={\rm peak},{\rm gh},{\rm uv}),\quad \bar c_{\rm uv}=c_{\rm uv}}
\]
\hfill$\blacksquare$

